"use client";

import Link from "next/link";
import { FormEvent, useCallback, useEffect, useRef, useState, useSyncExternalStore } from "react";
import plan from "../career-plan.json";
import "./career.css";

type ProgressState = { taught: boolean; practiced: boolean; level: string; last: { note: string; at: string; evidence: string } | null };
type Day = { id: string; title: string; date: string; core: boolean; lessonIds: string[]; action: string; acceptance: string; minutes: number; language?: boolean; technicalMinutes?: number; germanMinutes?: number };
const technicalIds = plan.weeks.flatMap(week => week.days.flatMap(day => day.lessonIds));
const germanIds = plan.weeks.flatMap(week => week.german ? week.german.lessonIds : []);
const allIds = [...technicalIds, ...germanIds];
const fa = (n: number) => n.toLocaleString("de-DE");
const subscribe = () => () => {};
const dateNow = () => new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Berlin", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date());

export default function CareerPage() {
  const [states, setStates] = useState<Record<string, ProgressState>>({});
  const [connected, setConnected] = useState(false);
  const [error, setError] = useState("");
  const [selected, setSelected] = useState<Day | null>(null);
  const [busy, setBusy] = useState(false);
  const [recordKind, setRecordKind] = useState("practice");
  const [prompt, setPrompt] = useState("");
  const [notice, setNotice] = useState("");
  const dialog = useRef<HTMLDialogElement>(null);
  const promptDialog = useRef<HTMLDialogElement>(null);
  const lastRetry = useRef<{ fields: string; body: string } | null>(null);
  const today = useSyncExternalStore(subscribe, dateNow, () => "");
  const rest = plan.breaks.find(pause => today >= pause.start && today <= pause.end);
  const sync = useCallback(async () => {
    try {
      const response = await fetch("/api/learning-lab/progress", { cache: "no-store", signal: AbortSignal.timeout(6000) });
      const data = await response.json() as { roadmapId?: string; completionBasis?: string; states?: Record<string, ProgressState>; error?: string };
      if (!response.ok || data.roadmapId !== "thesis-predefense-2026" || data.completionBasis !== "practice" || !data.states) throw new Error(data.error || "Kein gültiger Lernstand empfangen.");
      if (allIds.some(id => typeof data.states?.[id]?.practiced !== "boolean")) throw new Error("Lektionsliste veraltet. Bitte den Lernserver neu starten.");
      setStates(data.states); setConnected(true);
    } catch { setConnected(false); }
  }, []);
  useEffect(() => {
    const initial = window.setTimeout(() => void sync(), 0);
    const timer = window.setInterval(() => void sync(), 3000);
    return () => { window.clearTimeout(initial); window.clearInterval(timer); };
  }, [sync]);
  const done = (day: Day) => day.lessonIds.every(id => states[id]?.practiced === true);
  const completed = allIds.filter(id => states[id]?.practiced === true).length;
  const next = plan.weeks.flatMap(w => w.days).find(day => !done(day));

  function openRecord(day: Day) { setSelected(day); setRecordKind("practice"); setError(""); lastRetry.current = null; dialog.current?.showModal(); }
  function openPrompt(day: Day) {
    setPrompt(`Bitte bearbeite mit mir ${day.id}: ${day.title}. Geplantes Datum: ${day.date}. Prüfe tatsächliches Datum, Ruhephasen und verfügbare Zeit. Schreibe auf Deutsch von links nach rechts und verwende verständliche Sätze.

Meine Aufgabe: ${day.action}
Nachweis: ${day.acceptance}

Frage zuerst nach meinem Vorwissen. Gib nur einen kleinen Schritt und warte auf meine eigene Antwort. Ich schreibe Code und Texte selbst. Korrigiere danach höchstens zwei wichtige Fehler und lass mich neu formulieren.

Für einen technischen Lerntag: 150 Minuten Facharbeit und 30 Minuten Deutsch im bisherigen Budget, mit Pausen. Deutsch: 10 Minuten hören oder lesen, 10 Minuten selbst sprechen, 10 Minuten selbst schreiben und korrigieren. In Ruhephasen keine zusätzlichen Aufgaben. Der sprachliche Ausgangspunkt wird zuerst geprüft; kein B2 oder C1 allein aus Lernzeit ableiten.

Fortschritts-IDs: ${day.lessonIds.join(", ")}
${day.language ? "Diese Deutschwoche benötigt eigene Sprachproben der aktiven Tage, einen eigenen Text, eine konkrete Rückmeldung und eine erneute Formulierung. Technische Arbeit allein zählt nicht." : "Erfasse technische Übungen und den Deutschnachweis der Woche getrennt."}
Lies den aktuellen Stand. Erfasse practice nur nach tatsächlich bearbeiteter eigener Übung mit evidence. Deutschwochen benötigen zusätzlich review. Erklärungen, generierte Lösungen und bestandene App-Tests sind kein Lernerfolg. Ohne aktives Werkzeug behaupte keine Speicherung. Bewerbungen, Veröffentlichung und Kosten verlangen meine eigene Entscheidung.
Stand beim Kopieren: ${JSON.stringify(Object.fromEntries(day.lessonIds.map(id => [id, states[id] ? { practiced: states[id].practiced, level: states[id].level } : { practiced: false }])))}`);
    setNotice(""); promptDialog.current?.showModal();
  }
  async function record(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (!selected || busy) return;
    const form = new FormData(event.currentTarget);
    const kind = String(form.get("kind")), note = String(form.get("note") || "").trim(), evidence = String(form.get("evidence") || "").trim();
    if (!note || (kind === "practice" && !evidence)) { setError("Eine Beschreibung und der Nachweis deiner eigenen Übung sind erforderlich."); return; }
    const review = String(form.get("review") || "").trim();
    if (kind === "practice" && selected.language && !review) { setError("Für die Deutschwoche ist eine konkrete Rückmeldung erforderlich."); return; }
    const fields = JSON.stringify({ lessonId: selected.id, kind, note, evidence, review });
    if (!lastRetry.current || lastRetry.current.fields !== fields) {
      const receipt = { schemaVersion: 1, roadmapId: "thesis-predefense-2026", events: [{ ...JSON.parse(fields), id: crypto.randomUUID(), at: new Date().toISOString(), source: "manual" }] };
      lastRetry.current = { fields, body: JSON.stringify(receipt) };
    }
    const body = lastRetry.current.body;
    setBusy(true); setError("");
    try {
      const response = await fetch("/api/learning-lab/progress", { method: "POST", headers: { "Content-Type": "application/json" }, body, signal: AbortSignal.timeout(8000) });
      const data = await response.json() as { error?: string }; if (!response.ok) throw new Error(data.error || "Nicht gespeichert.");
      lastRetry.current = null;
      await sync(); dialog.current?.close(); setNotice("Im gemeinsamen Lernspeicher erfasst. Andere Seiten aktualisieren sich automatisch.");
    } catch (e) { setError(e instanceof Error ? e.message : "Nicht gespeichert. Bitte erneut versuchen."); }
    finally { setBusy(false); }
  }

  return <main className="career-shell" lang="de" dir="ltr">
    <header className="career-hero">
      <div><p className="career-eyebrow" dir="ltr">STUDY TRACKER / SECHS MONATE</p><h1>Vom Verstehen<br />zum eigenen Portfolio</h1><p>{plan.title}</p><p className="career-dates"><bdi>{plan.start}</bdi> bis <bdi>{plan.end}</bdi> · 26 Wochen</p></div>
      <aside className="career-target"><span>Gehaltsziel · vorläufige Annahme</span><strong><bdi>70.000 €</bdi></strong><span>Jahresbrutto in Deutschland</span><p>Planungsziel, keine Gehalts- oder Einstellungsgarantie.</p></aside>
    </header>
    <nav className="career-links" aria-label="Lernwege"><Link href="/learning-lab">26-Tage-Roadmap und Übungen</Link><Link href="/">Bisheriger Forschungsplan</Link><a href="#weeks">Meine Wochen</a><a href="#deutsch">Deutschtraining</a><a href="#market">Grundlage des Berufsziels</a></nav>
    <section className="career-status" aria-live="polite"><div><strong>{fa(completed)} / {fa(allIds.length)}</strong><span>Bearbeitete Aufgaben mit Nachweis</span></div><progress value={completed} max={allIds.length} aria-label="Übungsfortschritt" /><p>{connected ? "● Gemeinsamer Lernspeicher verbunden" : "Nicht verbunden. Öffne OPEN-STUDY-WORKSPACE.cmd."}</p></section>
    <p className="career-note">Fachübungen: {fa(technicalIds.filter(id => states[id]?.practiced).length)} / {fa(technicalIds.length)} · Deutschwochen: {fa(germanIds.filter(id => states[id]?.practiced).length)} / {fa(germanIds.length)}.</p>
    <p className="career-note">Grün bedeutet: eigene Übung bearbeitet und Nachweis erfasst. Der Zähler misst weder Einstellungschancen noch Sprach- oder Fachniveau. Eine Erklärung oder generierter Code genügt nicht.</p>
    {notice && <p role="status" className="career-note">{notice}</p>}
    <details className="career-settings"><summary>Annahmen, Zeitbudget und Überprüfung</summary><p>{plan.assumptions.status}</p><p>Vorgeschlagene Richtung: <bdi>{plan.assumptions.role}</bdi></p><p>{plan.capacity}</p><p>{plan.salaryNote}</p><p>Wenn du das Ergebnis noch nicht unabhängig erstellen oder erklären kannst, wiederhole die Fähigkeit mit einer kleineren Übung. Das Kalenderdatum ersetzt keine Voraussetzung.</p></details>
    {rest ? <section className="career-next"><h2>{rest.title}</h2><p>Bis <bdi>{rest.end}</bdi> gibt es keine neuen Aufgaben. Richte die Rückkehr nach deinen tatsächlichen Einschränkungen.</p></section> : next && <section className="career-next"><span>Erste offene Übung · Datum ist keine Pflicht</span><h2>{next.title}</h2><p>{next.action}</p><a href={`#week-${plan.weeks.find(w => w.days.some(d => d.id === next.id))?.number}`}>Zur Wochenkarte →</a></section>}
    <section className="career-next" id="deutsch"><h2>Deutsch für Studium und Beruf</h2><p>{plan.germanStrategy}</p><p><b>30 Minuten pro aktivem Lerntag:</b> 10 Minuten hören oder lesen, 10 Minuten selbst sprechen, 10 Minuten selbst schreiben und korrigieren. Bereits im Zeitbudget enthalten.</p>{plan.languageResources.map(resource => <p key={resource.url}><a href={resource.url} target="_blank" rel="noreferrer">{resource.title}</a>: {resource.note}</p>)}</section>
    <section id="weeks" className="career-weeks"><h2>Jede Woche ein überprüfbares Ergebnis</h2>{plan.weeks.map(week => {
      const count = week.days.filter(done).length, complete = week.days.length > 0 && count === week.days.length && (!week.german || done(week.german));
      return <details key={week.number} id={`week-${week.number}`} className={`career-week ${complete ? "is-complete" : ""}`} open={week.number === 1}>
        <summary><span className="career-week-number">{fa(week.number)}</span><span><small>{week.phase}</small><strong>{week.title}</strong><small><bdi>{week.start}</bdi> bis <bdi>{week.end}</bdi></small></span><span>{week.days.length ? `${fa(count)} / ${fa(week.days.length)} Facheinheiten` : "Ruhephase"}</span></summary>
        <div className="career-week-body"><p className="career-gate"><b>Abschlusskriterium: </b>{week.gate}</p>{[...week.days, ...(week.german ? [week.german] : [])].map((day: Day) => <article key={day.id} className={`career-day ${done(day) ? "is-complete" : ""}`} data-day={day.id}>
          <div><small><bdi>{day.id} · {day.date}</bdi> · {day.language ? "Wochenabschluss innerhalb der täglichen Deutschzeit" : "150 Minuten Facharbeit + 30 Minuten Deutsch, mit Pausen"}</small><h3>{day.title}</h3><span>{done(day) ? "✓ Übung bearbeitet" : "Übung offen"}</span></div><p>{day.action}</p><p className="career-acceptance">{day.acceptance}</p>
          {!day.core && states[day.id]?.last && <p className="career-last">Letzter Eintrag: {states[day.id].last?.note}</p>}
          <div className="career-day-actions"><button type="button" onClick={() => openPrompt(day)}>Unterrichtsauftrag öffnen</button>{day.core ? <Link href={`/learning-lab#${day.id}`}>Die Übungen dieses Tages öffnen</Link> : <button type="button" onClick={() => openRecord(day)} disabled={!connected}>{done(day) ? "Rückmeldung oder Korrektur erfassen" : "Erledigte Übung erfassen"}</button>}</div>
        </article>)}</div>
      </details>;
    })}</section>
    <section id="market" className="career-market"><h2>Das Gehaltsziel am Markt prüfen</h2><p>{plan.salaryNote}</p>{plan.sources.map(source => <article key={source.url}><a href={source.url} target="_blank" rel="noreferrer">{source.title}</a><p>{source.note}</p><small>Quelle geprüft am: <bdi>{source.checked}</bdi></small></article>)}</section>
    <dialog ref={dialog} className="career-dialog"><form onSubmit={record} key={selected?.id}>
      <h2>Eigene Arbeit erfassen · <bdi>{selected?.id}</bdi></h2><p>{selected?.action}</p><label>Art des Eintrags<select name="kind" value={recordKind} onChange={event => setRecordKind(event.target.value)}><option value="practice">Eigene Übung mit Nachweis, grün</option><option value="taught">Nur erklärt, bleibt offen</option><option value="reopen">Erneut zum Üben öffnen</option></select></label><label>Was hast du selbst bearbeitet?<textarea name="note" required maxLength={4000} /></label><label>Nachweis: eigene Antwort oder Pfad zur Arbeit mit Prüfergebnis<textarea name="evidence" maxLength={8000} required={recordKind === "practice"} /></label>{selected?.language && <label>Konkrete Rückmeldung und deine erneute Formulierung<textarea name="review" maxLength={8000} required={recordKind === "practice"} /></label>}<label className="career-confirm"><input type="checkbox" required /> Ich erfasse die tatsächliche Arbeit. Eine Erklärung oder fertigen Code zähle ich nicht als eigene Übung.</label>{error && <p role="alert">{error}</p>}<div className="career-day-actions"><button type="submit" disabled={busy}>{busy ? "Wird gespeichert …" : "Im gemeinsamen Lernspeicher speichern"}</button><button type="button" onClick={() => dialog.current?.close()} disabled={busy}>Abbrechen</button></div>
    </form></dialog>
    <dialog ref={promptDialog} className="career-dialog"><h2>Eigenständiger Unterrichtsauftrag</h2><textarea readOnly value={prompt} aria-label="Unterrichtsauftrag" rows={16} /><div className="career-day-actions"><button type="button" onClick={async () => { try { await navigator.clipboard.writeText(prompt); setNotice("Unterrichtsauftrag kopiert."); } catch { setNotice("Automatisches Kopieren fehlgeschlagen. Markiere und kopiere den Text."); } }}>Text kopieren</button><button type="button" onClick={() => promptDialog.current?.close()}>Schließen</button></div><p role="status">{notice}</p></dialog>
  </main>;
}
